Item.method_code:
const type = target.additional_data.viewerType;
const files = options.getState().files.get(type);
if (!files) {
	return { hidden: true };
}

const filesCount = files.size;
const tooltipTemplate = target.tooltipTemplate || target.tooltip_template;
const newTooltipTemplate = tooltipTemplate.replace('{0}', filesCount);
const roots = [...files.keys()];

const data = new Map();
files.forEach((item, id) => {
	const checked = control.selectedMenuItem === id;
	data.set(id, { ...item, checked, type: 'checkbox' });
});

return {
	data,
	hidden: false,
	roots,
	tooltip_template: newTooltipTemplate,
	tooltipTemplate
};
